/* Generated by wasmext from the WebAssembly module of hello: do not edit. The executable: main(), the glue of the module and the core of WASI; no Python. */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#ifdef _WIN32
#include <fcntl.h>
#include <io.h>
#endif
#include "hello_glue.h"

#if !HELLO_WASI || !HELLO_ONLY_WASI
#error "wasmext: an executable serves the imports of WASI and no others"
#endif
#ifndef HELLO_START
#error "wasmext: the module has no _start () -> ()"
#endif

typedef struct {
    int how;
    uint32_t value;
} run_end;

/* proc_exit and proc_raise: told before the program is marked as over */
static void run_ended(void *user, int how, uint32_t value) {
    run_end *e = (run_end *)user;
    e->how = how;
    e->value = value;
}

/* the strings of an array, each ended by a NUL, in one new buffer */
static char *run_pack(char **items, int count, size_t *size) {
    size_t total = 0;
    for (int i = 0; i < count; i++) total += strlen(items[i]) + 1;
    char *buffer = (char *)malloc(total ? total : 1), *at = buffer;
    for (int i = 0; buffer != NULL && i < count; i++) {
        size_t n = strlen(items[i]) + 1;
        memcpy(at, items[i], n);
        at += n;
    }
    *size = total;
    return buffer;
}

static hello_instance instance;

#ifdef _WIN32
#include <windows.h>
#include <shellapi.h>
/* the arguments as UTF-8: the narrow ones of the C runtime are in the code page of the console, and lose what it cannot hold */
static char **run_utf8_argv(int *count) {
    int n = 0;
    wchar_t **wide = CommandLineToArgvW(GetCommandLineW(), &n);
    if (wide == NULL) return NULL;
    char **out = (char **)calloc((size_t)n + 1, sizeof(char *));
    for (int i = 0; out != NULL && i < n; i++) {
        int size = WideCharToMultiByte(CP_UTF8, 0, wide[i], -1, NULL, 0, NULL, NULL);
        out[i] = (char *)malloc((size_t)size + 1);
        if (out[i] == NULL || WideCharToMultiByte(CP_UTF8, 0, wide[i], -1, out[i], size, NULL, NULL) == 0) return NULL;
    }
    *count = n;
    return out;
}
#endif

static void run_usage(FILE *to, const char *self) {
    fprintf(to,
            "usage: %s [options] [--] [program-name [arguments]]\n"
            "  --env NAME=VALUE      an environment variable of the program (repeatable)\n"
            "  --dir HOST[::GUEST][:ro]\n"
            "                        a directory the program may reach, as GUEST (\"/\" by default); :ro: read only (repeatable)\n"
            "  --argv0 NAME          the name the program has for itself (else the first argument that is not an option)\n"
            "  --version             print the name of the module and of wasmext\n"
            "  -h, --help            this text\n"
            "the program ends with the code of proc_exit, 134 on a trap, 2 when the options are wrong\n",
            self);
}

int main(int argc, char **argv) {
#ifdef _WIN32
    _setmode(0, _O_BINARY);  /* the bytes of the program, not text: no "\n" turned into "\r\n" */
    _setmode(1, _O_BINARY);
    _setmode(2, _O_BINARY);
    {
        char **utf8 = run_utf8_argv(&argc);
        if (utf8 != NULL) argv = utf8;
    }
#endif
    char **env = (char **)calloc((size_t)argc + 1, sizeof(char *));
    char **dirs = (char **)calloc((size_t)argc + 1, sizeof(char *));
    const char *argv0 = NULL;
    int nenv = 0, ndirs = 0, i = 1;
    for (; i < argc; i++) {  /* the options come first, then the program, then its arguments */
        const char *a = argv[i];
        int more = i + 1 < argc;
        if (strcmp(a, "--") == 0) {
            i++;
            break;
        } else if (strcmp(a, "-h") == 0 || strcmp(a, "--help") == 0) {
            run_usage(stdout, argv[0]);
            return 0;
        } else if (strcmp(a, "--version") == 0) {
            printf("hello (wasmext 0.0.0.dev259+g9dcf3c1eb)\n");
            return 0;
        } else if (strcmp(a, "--env") == 0 || strcmp(a, "--dir") == 0 || strcmp(a, "--argv0") == 0) {
            if (!more) {
                fprintf(stderr, "%s: %s needs a value\n", argv[0], a);
                return 2;
            }
            char *value = argv[++i];
            if (strcmp(a, "--env") == 0) {
                const char *eq = strchr(value, '=');
                if (eq == NULL || eq == value) {
                    fprintf(stderr, "%s: --env wants NAME=VALUE, not \"%s\"\n", argv[0], value);
                    return 2;
                }
                env[nenv++] = value;
            } else if (strcmp(a, "--dir") == 0) {
                dirs[ndirs++] = value;
            } else {
                argv0 = value;
            }
        } else if (a[0] == '-' && a[1] == '-') {
            fprintf(stderr, "%s: unknown option %s (-h for the list)\n", argv[0], a);
            return 2;
        } else {
            break;
        }
    }
    char *program = i < argc ? argv[i] : argv[0];  /* argv[0] of the program is the path it is given as */
    if (argv0 != NULL) {  /* named by --argv0: everything that follows is for the program */
        program = (char *)argv0;
        i--;
    }
    char **args = (char **)calloc((size_t)(argc - i) + 2, sizeof(char *));
    int nargs = 0;
    args[nargs++] = program;
    for (int k = i + 1; k < argc; k++) args[nargs++] = argv[k];

    wasmext_wasi_config config;
    memset(&config, 0, sizeof config);
    wasmext_wasi_preopen *preopens = (wasmext_wasi_preopen *)calloc((size_t)ndirs + 1, sizeof *preopens);
    for (int k = 0; k < ndirs; k++) {
        char *separator = strstr(dirs[k], "::");
        size_t length = strlen(dirs[k]);
        if (length >= 3 && strcmp(dirs[k] + length - 3, ":ro") == 0 && (separator != NULL || length > 3)) {
            dirs[k][length - 3] = '\0';
            preopens[k].readonly = 1;
        }
        if (separator != NULL) *separator = '\0';
        preopens[k].host = dirs[k];
#ifdef _WIN32
        {  /* the whole path, as Windows wants it for a name below it */
            char full[4096];
            if (_fullpath(full, dirs[k], sizeof full) != NULL) preopens[k].host = _strdup(full);
        }
#endif
        preopens[k].name = separator != NULL && separator[2] != '\0' ? separator + 2 : "/";
        preopens[k].name_len = strlen(preopens[k].name);
    }
    size_t args_size, env_size;
    config.args = run_pack(args, nargs, &args_size);
    config.args_size = args_size;
    config.argc = (uint32_t)nargs;
    config.env = run_pack(env, nenv, &env_size);
    config.env_size = env_size;
    config.envc = (uint32_t)nenv;
    config.preopens = preopens;
    config.npreopens = (size_t)ndirs;
    config.program = program;
    run_end ended = {0, 0};
    config.hooks.end = run_ended;
    config.user = &ended;

    wasm_rt_init();
    int error = 0;
    size_t bad = (size_t)-1;
    instance.wasi = wasmext_wasi_create(&config, &error, &bad);
    if (instance.wasi == NULL) {
        if (bad != (size_t)-1) fprintf(stderr, "%s: --dir %s: %s\n", argv[0], dirs[bad], strerror(error));
        else fprintf(stderr, "%s: cannot set up WASI: %s\n", argv[0], strerror(error));
        return 2;
    }
    wasmext_wasi_bind(instance.wasi, w2c_hello_memory(&instance.inst));
    hello_wasi_bind(&instance);
    int trapped = hello_glue_instantiate(&instance);
    if (!trapped) {
        HELLO_START(&instance.inst, &trapped);
    }
    int code = 0;
    if (ended.how == WASI_END_EXIT) {
        code = (int)ended.value;
    } else if (ended.how == WASI_END_SIGNAL) {
        fprintf(stderr, "%s: the program was ended by the signal %u\n", argv[0], (unsigned)ended.value);
        code = 134;
    } else if (trapped) {
        fprintf(stderr, "trap: %s\n", wasm_rt_strerror((wasm_rt_trap_t)trapped));
        code = 134;
    }
    fflush(stdout);
    hello_glue_free(&instance);
    wasmext_wasi_destroy(instance.wasi);
    return code;
}
